Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
nilfs2: Fix potential block overflow that cause system hang

When a user executes the FITRIM command, an underflow can occur when
calculating nblocks if end_block is too small. Since nblocks is of
type sector_t, which is u64, a negative nblocks value will become a
very large positive integer. This ultimately leads to the block layer
function __blkdev_issue_discard() taking an excessively long time to
process the bio chain, and the ns_segctor_sem lock remains held for a
long period. This prevents other tasks from acquiring the ns_segctor_sem
lock, resulting in the hang reported by syzbot in [1].

If the ending block is too small, typically if it is smaller than 4KiB
range, depending on the usage of the segment 0, it may be possible to
attempt a discard request beyond the device size causing the hang.

Exiting successfully and assign the discarded size (0 in this case)
to range->len.

Although the start and len values in the user input range are too small,
a conservative strategy is adopted here to safely ignore them, which is
equivalent to a no-op; it will not perform any trimming and will not
throw an error.

[1]
task:segctord state:D stack:28968 pid:6093 tgid:6093  ppid:2 task_flags:0x200040 flags:0x00080000
Call Trace:
 rwbase_write_lock+0x3dd/0x750 kernel/locking/rwbase_rt.c:272
 nilfs_transaction_lock+0x253/0x4c0 fs/nilfs2/segment.c:357
 nilfs_segctor_thread_construct fs/nilfs2/segment.c:2569 [inline]
 nilfs_segctor_thread+0x6ec/0xe00 fs/nilfs2/segment.c:2684

[ryusuke: corrected part of the commit message about the consequences]

Fixes: 82e11e857be3 ("nilfs2: add nilfs_sufile_trim_fs to trim clean segs")
Reported-by: syzbot+7eedce5eb281acd832f0@syzkaller.appspotmail.com
Closes: https://syzkaller.appspot.com/bug?extid=7eedce5eb281acd832f0
Signed-off-by: Edward Adam Davis <eadavis@qq.com>
Signed-off-by: Ryusuke Konishi <konishi.ryusuke@gmail.com>
Cc: stable@vger.kernel.org
Signed-off-by: Viacheslav Dubeyko <slava@dubeyko.com>

Here is the root cause:
Underflow when calculating nblocks (end_block - start_block + 1) due to end_block being too small, causing a huge positive value for sector_t, leading to excessive discard processing and system hang.

Here is the patch:
  */
 int nilfs_sufile_trim_fs(struct inode *sufile, struct fstrim_range *range)
 {
 	struct the_nilfs *nilfs = sufile->i_sb->s_fs_info;
 	struct buffer_head *su_bh;
 	struct nilfs_segment_usage *su;
 	size_t offset;
 	void *kaddr;
 	size_t n, i, susz = NILFS_MDT(sufile)->mi_entry_size;
 	sector_t seg_start, seg_end, start_block, end_block;
 	sector_t start = 0, nblocks = 0;
 	u64 segnum, segnum_end, minlen, len, max_blocks, ndiscarded = 0;
 	int ret = 0;
 	unsigned int sects_per_block;

 	sects_per_block = (1 << nilfs->ns_blocksize_bits) /
 			bdev_logical_block_size(nilfs->ns_bdev);
 	len = range->len >> nilfs->ns_blocksize_bits;
 	minlen = range->minlen >> nilfs->ns_blocksize_bits;
 	max_blocks = ((u64)nilfs->ns_nsegments * nilfs->ns_blocks_per_segment);

 	if (!len || range->start >= max_blocks << nilfs->ns_blocksize_bits)
 		return -EINVAL;

 	start_block = (range->start + nilfs->ns_blocksize - 1) >>
 			nilfs->ns_blocksize_bits;

 	/*
 	 * range->len can be very large (actually, it is set to
 	 * ULLONG_MAX by default) - truncate upper end of the range
 	 * carefully so as not to overflow.
 	 */
 	if (max_blocks - start_block < len)
 		end_block = max_blocks - 1;
 	else
 		end_block = start_block + len - 1;

+	if (end_block < nilfs->ns_first_data_block)
+		goto out;
+
 	segnum = nilfs_get_segnum_of_block(nilfs, start_block);
 	segnum_end = nilfs_get_segnum_of_block(nilfs, end_block);

 	down_read(&NILFS_MDT(sufile)->mi_sem);

 	while (segnum <= segnum_end) {
 		n = nilfs_sufile_segment_usages_in_block(sufile, segnum,
 				segnum_end);

 		ret = nilfs_sufile_get_segment_usage_block(sufile, segnum, 0,
 							   &su_bh);
 		if (ret < 0) {
 			if (ret != -ENOENT)
 				goto out_sem;
 			/* hole */
 			segnum += n;
 			continue;
 		}

 		offset = nilfs_sufile_segment_usage_offset(sufile, segnum,
 							   su_bh);
 		su = kaddr = kmap_local_folio(su_bh->b_folio, offset);
 		for (i = 0; i < n; ++i, ++segnum, su = (void *)su + susz) {
 			if (!nilfs_segment_usage_clean(su))
 				continue;

 			nilfs_get_segment_range(nilfs, segnum, &seg_start,
 						&seg_end);

 			if (!nblocks) {
 				/* start new extent */
 				start = seg_start;
 				nblocks = seg_end - seg_start + 1;
 				continue;
 			}

 			if (start + nblocks == seg_start) {
 				/* add to previous extent */
 				nblocks += seg_end - seg_start + 1;
 				continue;
 			}

 			/* discard previous extent */
 			if (start < start_block) {
 				nblocks -= start_block - start;
 				start = start_block;
 			}

 			if (nblocks >= minlen) {
 				kunmap_local(kaddr);

 				ret = blkdev_issue_discard(nilfs->ns_bdev,
 						start * sects_per_block,
 						nblocks * sects_per_block,
 						GFP_NOFS);
 				if (ret < 0) {
 					put_bh(su_bh);
 					goto out_sem;
 				}

 				ndiscarded += nblocks;
 				offset = nilfs_sufile_segment_usage_offset(
 					sufile, segnum, su_bh);
 				su = kaddr = kmap_local_folio(su_bh->b_folio,
 							      offset);
 			}

 			/* start new extent */
 			start = seg_start;
 			nblocks = seg_end - seg_start + 1;
 		}
 		kunmap_local(kaddr);
 		put_bh(su_bh);
 	}


 	if (nblocks) {
 		/* discard last extent */
 		if (start < start_block) {
 			nblocks -= start_block - start;
 			start = start_block;
 		}
 		if (start + nblocks > end_block + 1)
 			nblocks = end_block - start + 1;

 		if (nblocks >= minlen) {
 			ret = blkdev_issue_discard(nilfs->ns_bdev,
 					start * sects_per_block,
 					nblocks * sects_per_block,
 					GFP_NOFS);
 			if (!ret)
 				ndiscarded += nblocks;
 		}
 	}

 out_sem:
 	up_read(&NILFS_MDT(sufile)->mi_sem);

+out:
 	range->len = ndiscarded << nilfs->ns_blocksize_bits;
 	return ret;
 }



